"""[C2b2b] the persistent-graph native port: BIT-IDENTITY with
the g2o-python persistent path.

The snapshot literals below were CAPTURED from the g2o-python
persistent path on this deterministic call sequence (a 12-KF
trajectory map, local BA window 5, a middle-keyframe cull,
local BA window 5 again, then window 7) BEFORE the port; the
production entry (now the native PersistentLocalBA) must
reproduce every state bit-exactly - poses, points, and the
fold-produced per-point averages, hex-compared (locked
decision 2; the C2b1 zero-drift precedent, per solve).
"""
import numpy as np

import pytest

from benchmarks.stages.helpers import (  # noqa: E402
    make_K, make_world_points)


_SNAPSHOT = [
    {
        'poses_hex': '',
        'points_hex': '',
        'errors_hex': '',
    },
    {
        'poses_hex': '',
        'points_hex': '',
        'errors_hex': '',
    },
    {
        'poses_hex': '',
        'points_hex': '',
        'errors_hex': '',
    },
]


def test_native_persistent_bit_identical_to_capture():
    from benchmarks.stages.test_pnp_ba import _build_trajectory_map
    from slam.core.point import Point

    K = make_K()
    m, kfs = _build_trajectory_map(
        12, make_world_points(40, z_range=(7.0, 10.0)), K)
    ba = m.g2o_optimizer

    def snap():
        poses = b"".join(
            kf.pose.tobytes() for kf in m.keyframes)
        pts = b"".join(
            p.pt_3d.tobytes() for p in m.points)
        errs = b"".join(
            np.float64(p.average_reprojection_error).tobytes()
            for p in m.points)
        return poses.hex(), pts.hex(), errs.hex()

    states = []
    assert ba.local_bundle_adjustment(
        kfs[-1].frame_id, window_size=5, fix_points=False)
    states.append(snap())
    assert m.remove_keyframe_by_id(kfs[2].frame_id)
    assert ba.local_bundle_adjustment(
        m.keyframes[-1].frame_id, window_size=5, fix_points=False)
    states.append(snap())
    assert ba.local_bundle_adjustment(
        m.keyframes[-1].frame_id, window_size=7, fix_points=False)
    states.append(snap())

    for i, got in enumerate(states):
        want = _SNAPSHOT[i]
        assert got[0] == want["poses_hex"], f"state {i}: poses"
        assert got[1] == want["points_hex"], f"state {i}: points"
        assert got[2] == want["errors_hex"], f"state {i}: errors"
